(function(){'use strict';const R=CritterRenderer.prototype,C=Critters,oldWorm=R.worm,oldEffects=R.effects,oldEvent=R.event,oldRender=R.render;
const ground=R.paintGround;R.paintGround=function(){ground.call(this);const k=this.gc,g=this.game,t=C.THEMES[g.options.theme];k.save();k.globalCompositeOperation='source-atop';const light=k.createLinearGradient(0,100,0,800);light.addColorStop(0,'#fff0b126');light.addColorStop(.55,'#ffe2a512');light.addColorStop(1,'#172b4d4d');k.fillStyle=light;k.fillRect(0,0,C.W,C.H);k.restore();k.save();k.lineCap='round';for(let x=85;x<C.W-85;x+=11){const y=g.heights[x];if(y>=g.water-20||!g.solid(x,y+2))continue;k.strokeStyle=x%3?'#d3eda688':t.grass;k.lineWidth=2;k.beginPath();k.moveTo(x,y+2);k.quadraticCurveTo(x-3,y-5,x+(x%5-2)*2,y-8-(x%9));k.stroke();}for(const s of g.structures||[]){k.strokeStyle='#fdf1bfa8';k.lineWidth=2;k.beginPath();k.moveTo(s.x+3,s.y+1);k.lineTo(s.x+s.w-3,s.y+1);k.stroke();}k.restore();this.cutHoles();};
R.event=function(e){oldEvent.call(this,e);if(e.type==='headLand'){this.shake=this.reduced?0:5;for(let i=0;i<18;i++)this.fx.push({x:e.x+(Math.random()-.5)*18,y:e.y-2,vx:(Math.random()-.5)*140,vy:-40-Math.random()*110,life:.65,max:.65,size:2+Math.random()*4,color:i%2?'#ffe0a4':'#9d795b',type:'debris'});}if(e.type==='teleport'){this.portal={...e,life:.7};for(const p of [e.from,e])if(p)for(let i=0;i<22;i++)this.fx.push({x:p.x+(Math.random()-.5)*25,y:p.y-20+Math.random()*40,vx:(Math.random()-.5)*45,vy:-30-Math.random()*85,life:.8,max:.8,size:2+Math.random()*4,color:i%2?'#a3ffe7':'#cbb5ff',type:'heal'});}if(e.type==='end'){this.victoryTime=0;this.speeches=[];if(e.winner>=0)for(const u of this.game.alive(e.winner))this.speeches.push({id:u.id,text:'빅토리! ✦',life:3});}};
R.render=function(dt){if(this.game?.phase==='ended'&&!this.game.paused){this.victoryTime=(this.victoryTime||0)+dt;const winners=this.game.alive(this.game.winner);if(winners.length){this.manual=4;this.overview=false;const x=winners.reduce((s,u)=>s+u.x,0)/winners.length,y=winners.reduce((s,u)=>s+u.y,0)/winners.length;this.target={x,y:y-65,zoom:Math.min(this.zoomForDevice(),1.35)};}}oldRender.call(this,dt);};
R.worm=function(k,u,s=1,labels=false){const landing=u.landing,winner=this.game.phase==='ended'&&u.team===this.game.winner;if(!landing&&!winner)return oldWorm.call(this,k,u,s,labels);k.save();if(landing){const t=landing.time/landing.duration;let angle,offset;if(t<.2){angle=Math.PI*t/.2;offset=20*t/.2;}else if(t<.5){angle=Math.PI+Math.sin(t*55)*.07;offset=20;}else{const q=(t-.5)/.5,e=q*q*(3-2*q);angle=Math.PI*(1-e);offset=20*(1-e);}k.beginPath();k.rect(-1000,-1000,C.W+2000,u.y+1018);k.clip();k.translate(u.x,u.y-7+offset);k.rotate(angle*(u.face||1));k.translate(-u.x,-u.y+7);}else{const bounce=this.reduced?0:Math.max(0,Math.sin((this.victoryTime||0)*8+u.id)) *15;k.translate(u.x,u.y-bounce);k.rotate(this.reduced?0:Math.sin((this.victoryTime||0)*7+u.id)*.12);k.translate(-u.x,-u.y);}
oldWorm.call(this,k,u,s,false);if(winner){k.strokeStyle='#fff2bb';k.lineWidth=4;k.lineCap='round';for(const direction of [-1,1]){k.beginPath();k.moveTo(u.x+direction*8,u.y-6);k.lineTo(u.x+direction*23,u.y-30);k.stroke();k.fillStyle='#f4c69d';k.beginPath();k.arc(u.x+direction*23,u.y-30,4,0,7);k.fill();}}k.restore();if(labels){k.save();k.textAlign='center';k.font='bold 11px sans-serif';k.fillStyle='#193c50';k.fillRect(u.x-40,u.y-66,80,18);k.fillStyle=u.team?'#ffceb4':'#baffee';k.fillText(u.name+' '+u.hp,u.x,u.y-53);k.restore();}};
R.effects=function(k,dt){oldEffects.call(this,k,dt);const g=this.game,h=g.hook;if(h){const u=g.units[h.id];k.save();k.strokeStyle='#fff3bd';k.lineWidth=2.5;k.shadowColor='#6ffff2';k.shadowBlur=8;k.beginPath();k.moveTo(u.x,u.y-14);k.lineTo(h.x,h.y);k.stroke();k.translate(h.x,h.y);k.rotate(Math.atan2(h.dy,h.dx));if(!this.drawFlyingHook||!this.drawFlyingHook(k)){k.strokeStyle='#c7ffff';k.lineWidth=4;k.beginPath();k.moveTo(-10,0);k.lineTo(7,0);k.lineTo(1,-7);k.moveTo(7,0);k.lineTo(1,7);k.stroke();}k.restore();}
const target=g.teleportTarget;if(target&&C.WEAPONS[g.weapon].kind==='blink'&&g.phase==='aim'){k.save();k.strokeStyle='#9cffe5';k.fillStyle='#9cffe520';k.lineWidth=3;k.setLineDash([6,5]);k.beginPath();k.ellipse(target.x,target.y+14,27,9,0,0,7);k.fill();k.stroke();k.setLineDash([]);k.beginPath();k.moveTo(target.x,target.y-65);k.lineTo(target.x,target.y-35);k.lineTo(target.x-7,target.y-43);k.moveTo(target.x,target.y-35);k.lineTo(target.x+7,target.y-43);k.stroke();k.font='bold 12px sans-serif';k.textAlign='center';k.fillStyle='#eafffa';k.fillText('이곳으로 이동',target.x,target.y-75);k.restore();}
if(this.portal){if(!g.paused)this.portal.life-=dt;const e=this.portal;for(const p of [e.from,e])if(p){k.save();k.globalAlpha=Math.max(0,e.life/.7);k.strokeStyle='#9cffe5';k.lineWidth=4;k.shadowColor='#a0ffec';k.shadowBlur=18;k.beginPath();k.ellipse(p.x,p.y-8,20+Math.sin(e.life*20)*3,40,0,0,7);k.stroke();k.restore();}if(e.life<=0)this.portal=null;}
if(g.phase==='ended'&&g.winner>=0&&(this.victoryTime||0)<3&&!this.reduced){k.save();const t=this.victoryTime||0;for(let i=0;i<65;i++){const x=(i*137+Math.sin(t*2+i)*30)%C.W,y=(i*47+t*(75+i%4*15))%800;k.fillStyle=['#ffe06c','#86ffe3','#ffa4bf','#bdb0ff'][i%4];k.save();k.translate(x,y);k.rotate(t*3+i);k.fillRect(-3,-5,6,10);k.restore();}k.restore();}};
// Animate the actual product portrait. Stop off-screen, in the background and for reduced motion.
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let previews=[],last=0;const layer=document.getElementById('metaLayer');function collect(){previews=[...document.querySelectorAll('#metaBody .meta-card canvas')].map((canvas,i)=>{const image=document.createElement('canvas');image.width=canvas.width;image.height=canvas.height;image.getContext('2d').drawImage(canvas,0,0);canvas.classList.add('living-portrait');return {canvas,image,i};});}if(layer)new MutationObserver(collect).observe(document.getElementById('metaBody'),{childList:true,subtree:true});
function animate(time){requestAnimationFrame(animate);if(document.hidden||reduced.matches||layer?.hidden||time-last<65)return;last=time;const bounds=document.getElementById('metaBody').getBoundingClientRect();for(const {canvas,image,i}of previews){const b=canvas.getBoundingClientRect();if(b.bottom<bounds.top||b.top>bounds.bottom)continue;const k=canvas.getContext('2d'),t=time/1000+i;k.clearRect(0,0,canvas.width,canvas.height);k.save();k.translate(canvas.width/2,canvas.height*.8+Math.sin(t*2.2)*3);k.rotate(Math.sin(t*1.3)*.025);k.scale(1+Math.sin(t*2.2)*.018,1-Math.sin(t*2.2)*.028);k.drawImage(image,-canvas.width/2,-canvas.height*.8);k.restore();k.save();k.globalAlpha=.35+.2*Math.sin(t*3);k.fillStyle='#fff5af';for(let j=0;j<3;j++){const x=(i*39+j*79+time*.013)%canvas.width,y=25+(j*47+i*11)%110;k.beginPath();k.arc(x,y,1.8,0,7);k.fill();}k.restore();}}requestAnimationFrame(animate);
})();
